<script>$(function(){let filter='all',page=1,last=1,timer;$('.select2').select2({width:'100%',dropdownParent:$('#filterDrawer')});const esc=v=>$('<div>').text(v||'N/A').html();const params=()=>({filter,page,search:$('#search').val(),created_by:$('#createdBy').val(),date_from:$('#dateFrom').val(),date_to:$('#dateTo').val()});function load(){$.get("{{route('complaints.mobile-list')}}",params(),function(r){Object.keys(r.counts).forEach(k=>$('#count-'+k).text(r.counts[k]));$('#recordCount').text(r.counts.all+' records');last=r.last_page;$('#complaintRows').html(r.data.map((x,i)=>`<tr><td>${(r.current_page-1)*25+i+1}</td><td>${esc(x.date)}</td><td><a href="${x.detail_url}" class="text-info font-weight-bold">${esc(x.number)}</a></td><td>${esc(x.dealer)}</td><td>${esc(x.end_user)}</td><td>${esc(x.mobile)}</td><td>${esc(x.category)}</td><td>${esc(x.size)}</td><td>${esc(x.batch)}</td><td><span class="truncate" title="${esc(x.description)}">${esc(x.description)}</span></td><td>${esc(x.received_through)}</td><td><span class="status-label">${esc(x.status)}</span></td></tr>`).join(''));$('#empty').toggle(!r.data.length);$('#prev').prop('disabled',page<=1);$('#next').prop('disabled',page>=last)}).fail(()=>{$('#complaintRows').empty();$('#empty').text('Unable to load complaints').show()})}function drawer(open){$('#filterDrawer,#drawerOverlay').toggleClass('open',open)}$('.summary-btn').click(function(){filter=$(this).data('filter');page=1;$('.summary-btn').removeClass('active');$(this).addClass('active');load()});$('#search').on('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{page=1;load()},350)});$('#openFilter').click(()=>drawer(true));$('#closeFilter,#drawerOverlay').click(()=>drawer(false));$('#applyFilter').click(()=>{page=1;drawer(false);load()});$('#resetFilter').click(()=>{$('#createdBy').val('').trigger('change');$('#dateFrom,#dateTo').val('');page=1;drawer(false);load()});$('#exportBtn').click(()=>{let q=$.param(params());window.location="{{route('complaints.mobile-export')}}?"+q});$('#prev').click(()=>{if(page>1){page--;load()}});$('#next').click(()=>{if(page<last){page++;load()}});load()});</script>
